import itertools
from collections import deque

def find_cycles_from_vertex(adj, start, max_length):
    """Find all cycles starting from a vertex with length <= max_length using BFS."""
    cycles = []
    # BFS to find shortest paths
    # State: (current_vertex, path)
    queue = deque([(start, [start])])
    visited_paths = {(start,): True}

    while queue:
        vertex, path = queue.popleft()
        if len(path) > max_length:
            continue

        for neighbor in adj[vertex]:
            if neighbor == start and len(path) >= 3:
                # Found a cycle
                cycles.append(len(path))
            elif neighbor not in path and len(path) < max_length:
                new_path = path + [neighbor]
                path_tuple = tuple(sorted(new_path))
                if path_tuple not in visited_paths:
                    visited_paths[path_tuple] = True
                    queue.append((neighbor, new_path))

    return cycles

def check_girth(adj, n, min_girth):
    """Check if the graph has girth at least min_girth."""
    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Found a cycle
                    cycle_length = dist[u] + dist[v] + 1
                    if cycle_length < min_girth:
                        return False, cycle_length

    return True, None

def is_k_colorable(adj, n, k):
    """Check if graph is k-colorable using backtracking."""
    colors = [-1] * n

    def backtrack(vertex):
        if vertex == n:
            return True

        for color in range(k):
            # Check if this color is valid
            valid = True
            for neighbor in adj[vertex]:
                if neighbor < vertex and colors[neighbor] == color:
                    valid = False
                    break

            if valid:
                colors[vertex] = color
                if backtrack(vertex + 1):
                    return True
                colors[vertex] = -1

        return False

    return backtrack(0)

